svg.script:
/*  */
(function() {
  const svg = document.getElementById('fm1p9-svg-main');
  if (!svg) return;

  // Troca de Tabs (Máquina de Estados)
  function setActiveTab(tabName) {
    svg.setAttribute('data-active-tab', tabName);
  }

  const btnMuscular = document.getElementById('fm1p9-btn-muscular');
  const btnPlaca = document.getElementById('fm1p9-btn-placa');
  const btnNeuronio = document.getElementById('fm1p9-btn-neuronio');

  if (btnMuscular) {
    btnMuscular.addEventListener('click', function() { setActiveTab('muscular'); });
    btnMuscular.addEventListener('keydown', function(e) { if (e.key === 'Enter' || e.key === ' ') { setActiveTab('muscular'); e.preventDefault(); } });
  }

  if (btnPlaca) {
    btnPlaca.addEventListener('click', function() { setActiveTab('placa'); });
    btnPlaca.addEventListener('keydown', function(e) { if (e.key === 'Enter' || e.key === ' ') { setActiveTab('placa'); e.preventDefault(); } });
  }

  if (btnNeuronio) {
    btnNeuronio.addEventListener('click', function() { setActiveTab('neuronio'); });
    btnNeuronio.addEventListener('keydown', function(e) { if (e.key === 'Enter' || e.key === ' ') { setActiveTab('neuronio'); e.preventDefault(); } });
  }

  // Tooltip Mouse-Follow Engine
  const tooltip = document.getElementById('fm1p9-tooltip');
  const tipBg = document.getElementById('fm1p9-tip-bg');
  const tipText = document.getElementById('fm1p9-tip-text');
  const hotspots = svg.querySelectorAll('[data-fm1p9-tooltip]');

  hotspots.forEach(function(hs) {
    hs.addEventListener('mousemove', function(e) {
      const msg = hs.getAttribute('data-fm1p9-tooltip');
      if (!msg || !tooltip) return;

      // Converter coordenadas de mouse para SVG
      const pt = svg.createSVGPoint();
      pt.x = e.clientX;
      pt.y = e.clientY;
      const svgPt = pt.matrixTransform(svg.getScreenCTM().inverse());

      tipText.textContent = msg;

      // Ajustar largura dinâmica da caixa de tooltip
      const textWidth = Math.max(140, msg.length * 5.8);
      if (tipBg) tipBg.setAttribute('width', textWidth + 20);

      let posX = svgPt.x + 12;
      let posY = svgPt.y + 12;

      // Evitar estravasamento da borda direita do viewBox (960px)
      if (posX + textWidth + 30 > 960) {
        posX = svgPt.x - textWidth - 25;
      }

      tooltip.setAttribute('transform', 'translate(' + posX + ',' + posY + ')');
      tooltip.setAttribute('opacity', '1');
    });

    hs.addEventListener('mouseleave', function() {
      if (tooltip) tooltip.setAttribute('opacity', '0');
    });
  });
})();
/*  */
